class Graph:
    def __init__(self):
        self.adj = set()

    def add_edge(self, a, b):
        if a > b:
            a, b = b, a
        if (a, b) not in self.adj:
            self.adj.add((a, b))
        self.adj.add((b, a))

    def is_connected(self):
        connected = set()
        start = sorted(list(self.adj))[0] if self.adj else None

        # Collect all nodes
        all_nodes = set(cell for p1, p2 in self.adj for cell in [p1, p2])
        if not all_nodes:
            return True

        visited = set()
        queue = [sorted(list(all_nodes))[0]]
        visited.add(queue[0])

        while queue:
            node = queue.pop(0)
            for neighbor, _ in self.adj:
                if neighbor == node:
                    continue
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        return len(visited) == len(all_nodes)

